target.command:
cd /home/john/mynotes/deterministic_equidistribution_theory/c_suite/out_large
echo "### A height-tail slope (octave 24, aperture 4 row) ###"
awk -F, '!/^#/ && $1==24 && $3==4 {seeds=$2; prev="";
   for(H=2;H<=14;H++){c=$(7+H); P=c/seeds; l=log(P)/log(2); s=(prev==""?0:l-prev);
     printf "H=%2d tail=%-9d log2P=%7.3f slope=%6.3f\n",H,c,l,s; prev=l}}' height_tail.csv | head -13
echo "### B tilt-law middle bulk (octave 26, height mode) ###"
awk -F, '!/^#/ && $5=="middle" && $7>=16 {n++; p1+=$8;p2+=$9;p3+=$10;p4+=$11; epd+=$17; k1+=$14; k0+=$13}
  END{if(n)printf "middle segs(>=16)=%d  p1=%.4f p2=%.4f p3=%.4f p4=%.4f\n  entropy/digit=%.4f (tgt .8113)  KL_p1=%.4f KL_ann=%.4f\n  [annealed .5/.25/.125/.0625 ; critical .75/.1875/.0469/.0117]\n",n,p1/n,p2/n,p3/n,p4/n,epd/n,k1/n,k0/n}' tilt_law.csv
echo "### D post-exit taboo (octave 24) ###"
awk -F, '!/^#/ && $1!="event_id" && $5>=16 {n++; m+=$8; if($8<1)lt++; k1+=$7; k0+=$6}
  END{if(n)printf "windows=%d  mean M_post(1)=%.4f  frac(<1)=%.3f  KL_to_p=%.4f  KL_to_p1=%.4f\n",n,m/n,lt/n,k0/n,k1/n}' post_exit.csv
